import React from 'react';
import { View, Text, StyleSheet } from 'react-native';

//First navigate to GrusGorls folder in terminal using cd then navigate to Product folder using cd Product
//To run server use npm start in terminal
//To see what it looks like in app form, right click inspect and click on the app tab
// ctrl + c to stop server

export default function NavBar() {
  return (
    <View style={StyleSheet.navbar}>
      <Text style={StyleSheet.title}>KindFins</Text>
    </View>
  )
}

function App() {
  return (
    <><div>
      <head><title>ThriftApp</title></head>
    </div><div>
        <h1>Welcome to ThriftApp</h1>
      </div></>
  );
}

const styles = StyleSheet.create({ 
  navbar: { 
    height: 70, 
    backgroundColor: '#222', 
    justifyContent: 'center', 
    paddingHorizontal: 20, 
  }, 
  title: { 
    color: '#fff', 
    fontSize: 22, 
    fontWeight: '600', 
  }, 
});

